from typing import Union
from easyvolcap.utils.base_utils import dotdict
import numpy as np
import torch

# If the input is a tuple or a list, recursively call add_batch on each element
if isinstance(batch, (tuple, list)):
    return type(batch)(add_batch(item) for item in batch)

# If the input is a dictionary, convert it to a dotdict and recursively call add_batch on each value
elif isinstance(batch, dict):
    batch = dotdict(batch)
    for key, value in batch.items():
        batch[key] = add_batch(value)
    return batch

# If the input is a torch.Tensor or a numpy.ndarray, add a new dimension at the zeroth position
elif isinstance(batch, (torch.Tensor, np.ndarray)):
    return batch.unsqueeze(0) if isinstance(batch, torch.Tensor) else batch[np.newaxis, ...]

# If the input is of any other type, raise a TypeError
else:
    raise TypeError(f"Unsupported type: {type(batch)}")

